import{_ as o,o as t,c as a,a0 as r}from"./chunks/framework.CSN5ZNqX.js";const p=JSON.parse('{"title":"Cloud Computing (CSE415)","description":"","frontmatter":{},"headers":[],"relativePath":"cse415/index.md","filePath":"cse415/index.md"}'),n={name:"cse415/index.md"};function l(s,e,i,c,u,d){return t(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="cloud-computing-cse415" tabindex="-1">Cloud Computing (CSE415) <a class="header-anchor" href="#cloud-computing-cse415" aria-label="Permalink to &quot;Cloud Computing (CSE415)&quot;">​</a></h1><blockquote><p>This course teaches senior undergraduate Computer Engineering students the fundamental concepts of cloud computing, and provides a hands-on experience of the area that prepares them for the job market.</p></blockquote><h2 id="null" tabindex="-1">NULL <a class="header-anchor" href="#null" aria-label="Permalink to &quot;NULL&quot;">​</a></h2><h2 id="welcome-to-the-course" tabindex="-1">Welcome to the course <a class="header-anchor" href="#welcome-to-the-course" aria-label="Permalink to &quot;Welcome to the course&quot;">​</a></h2><ul><li>📄 <strong><a href="/courses/courses/files/CSE415/General%20Guidelines.pdf">General Guidelines</a></strong> (<code>General Guidelines.pdf</code>)</li><li>📄 <strong><a href="/courses/courses/files/CSE415/About.pdf">About the course</a></strong> (<code>About.pdf</code>)</li><li>📄 <strong><a href="/courses/courses/files/CSE415/AWS.pdf">Create AWS account</a></strong> (<code>AWS.pdf</code>)</li><li>📄 <strong><a href="/courses/courses/files/CSE415/Github.pdf">Github Student Developer Pack</a></strong> (<code>Github.pdf</code>)</li></ul><h2 id="lectures" tabindex="-1">Lectures <a class="header-anchor" href="#lectures" aria-label="Permalink to &quot;Lectures&quot;">​</a></h2><ul><li>📄 <strong><a href="/courses/courses/files/CSE415/Lecture%201%20-%20Introduction.pdf">Lecture 1 - Introduction</a></strong> (<code>Lecture 1 - Introduction.pdf</code>)</li><li>📄 <strong><a href="/courses/courses/files/CSE415/Lecture%203%20-%20AWS.pdf">Lecture 3 - AWS</a></strong> (<code>Lecture 3 - AWS.pdf</code>)</li><li>📄 <strong><a href="/courses/courses/files/CSE415/Lecture%204%20-%20Containers.pdf">Lecture 4 - Containers</a></strong> (<code>Lecture 4 - Containers.pdf</code>)</li></ul><h2 id="assignments" tabindex="-1">Assignments <a class="header-anchor" href="#assignments" aria-label="Permalink to &quot;Assignments&quot;">​</a></h2><h3 id="📝-assignment-1-course-project-abstract" tabindex="-1">📝 Assignment 1 - Course Project Abstract <a class="header-anchor" href="#📝-assignment-1-course-project-abstract" aria-label="Permalink to &quot;📝 Assignment 1 - Course Project Abstract&quot;">​</a></h3><p>Prepare and submit a 1-page description of your suggested course project.</p><p>The course project is any application that can be hosted in the cloud. Examples include a personal website, a course website, a department or college website, an online coding platform, an online game, an online machine learning tool, etc.</p><p>Each project should be completed by only one student during the semester. A small-group project could be allowed as an exception (on a case-by-case basis) depending on the project size.</p><h3 id="📝-assignment-2-project-report-and-demo" tabindex="-1">📝 Assignment 2 - Project Report and Demo <a class="header-anchor" href="#📝-assignment-2-project-report-and-demo" aria-label="Permalink to &quot;📝 Assignment 2 - Project Report and Demo&quot;">​</a></h3><p>Final Report of course project should include the following information:</p><ul><li>Project Title</li><li>Project Team</li><li>Project Abstract</li><li>Description of the end product of the project, e.g. database system, web interface, ...</li><li>Link to online project demo, if available</li><li>Project full description and details</li><li>Specific role of each team member in the project, if team project</li><li>Reason why you chose that project</li><li>Your plan to integrate that project into another one in the future, e.g. graduation project, explaining how</li><li>Cloud platform used for the project</li><li>Other platforms you considered using</li><li>Reason why you ended up using the platform of your choice</li><li>Platform tools used for your project, e.g. Amazon DynamoDB</li><li>Reason why you chose those tools over other tools of the platform</li><li>Any challenges you faced with the selected platform and tools</li><li>What you did to overcome those challenges</li><li>Any other details you find relevant</li></ul><p>Project demo can be one or more of the following:</p><ul><li>Online page showing the end product of the project</li><li>Screencast of how you use your end product</li><li>Any other format you find suitable that fully shows the features of your project</li></ul><h2 id="labs" tabindex="-1">Labs <a class="header-anchor" href="#labs" aria-label="Permalink to &quot;Labs&quot;">​</a></h2><ul><li>🔗 <strong><a href="https://www.qwiklabs.com/catalog_lab/177" target="_blank" rel="noreferrer">Lab 2 - Introduction to Amazon S3</a></strong></li><li>📄 <strong><a href="/courses/courses/files/CSE415/AWS.pdf">Lab 0 - Create an AWS account</a></strong> (<code>AWS.pdf</code>)</li><li>🔗 <strong><a href="https://www.awseducate.com/" target="_blank" rel="noreferrer">Lab 1 - Get Familiar with Amazon EC2</a></strong></li><li>🔗 <strong><a href="https://www.qwiklabs.com/catalog_lab/232" target="_blank" rel="noreferrer">Lab 3 - Introduction to Amazon DynamoDB</a></strong></li><li>🔗 <strong><a href="https://www.qwiklabs.com/catalog_lab/252" target="_blank" rel="noreferrer">Lab 4 - Introduction to Amazon Machine Learning</a></strong></li><li>🔗 <strong><a href="https://www.qwiklabs.com/catalog_lab/1281" target="_blank" rel="noreferrer">Lab 5 - Get familiar with GCP</a></strong></li><li>🔗 <strong><a href="https://www.qwiklabs.com/catalog_lab/702" target="_blank" rel="noreferrer">Lab 6 - Introduction to the GCP App Engine</a></strong></li><li>🔗 <strong><a href="https://www.qwiklabs.com/catalog_lab/923" target="_blank" rel="noreferrer">Lab 7 - Introduction to the GCP Datastore</a></strong></li><li>🔗 <strong><a href="https://www.qwiklabs.com/catalog_lab/363" target="_blank" rel="noreferrer">Lab 9 - Firebase Web</a></strong></li><li>🔗 <strong><a href="https://www.qwiklabs.com/catalog_lab/684" target="_blank" rel="noreferrer">Lab 8 - Introduction to the Google BigQuery</a></strong></li></ul>',19)])])}const f=o(n,[["render",l]]);export{p as __pageData,f as default};
